/**
 * Generates `server/db/migrations/0001_auth.sql` from Better Auth's own
 * migration planner, run against a throwaway in-memory db with the exact
 * options `createAuth` builds (`buildOptions`, factored out of `auth.ts`
 * for this). Check the generated file in; re-run this (`npm run
 * db:gen-auth -w server`) and add a *new* migration file (never hand-edit
 * `0001_auth.sql`) whenever a Better Auth upgrade changes the schema — the
 * schema-drift guard test in `test/db/migrate.test.ts` fails loudly if it
 * does and this hasn't been re-run.
 *
 * API confirmed against the installed better-auth@1.7.18: `getMigrations`
 * is NOT re-exported from the `better-auth/db` entry point (that only
 * re-exports from `@better-auth/core/db`) — the public entry point that
 * carries it is `better-auth/db/migration`.
 */
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import Database from 'better-sqlite3';
import { getMigrations } from 'better-auth/db/migration';
import { createLogger } from '@bellhop/shared/logger';
import { buildOptions } from '../src/auth/auth.js';

/** Kept in sync with the tables Better Auth's email+password + api-key plugin configuration creates. */
const AUTH_TABLES = ['user', 'session', 'account', 'verification', 'apikey'] as const;

function dropOrder(): readonly string[] {
  // Children before parents: session/account reference user.
  return ['session', 'account', 'apikey', 'verification', 'user'];
}

async function main(): Promise<void> {
  const logger = createLogger({ name: 'gen-auth-migration', level: 'silent' });
  const db = new Database(':memory:');

  const options = buildOptions({
    db,
    secret: 'gen-auth-migration-placeholder',
    baseUrl: 'http://localhost:3000',
    logger,
  });

  const { toBeCreated, toBeAdded, compileMigrations } = await getMigrations(options);
  const plannedTables = [...toBeCreated.map((t) => t.table), ...toBeAdded.map((t) => t.table)].sort();
  const expectedTables = [...AUTH_TABLES].sort();

  if (JSON.stringify(plannedTables) !== JSON.stringify(expectedTables)) {
    throw new Error(
      `better-auth planned tables [${plannedTables.join(', ')}], expected [${expectedTables.join(', ')}] — ` +
        'update AUTH_TABLES/dropOrder in this script to match before regenerating the migration',
    );
  }

  const upSql = await compileMigrations();
  const downSql = dropOrder()
    .map((table) => `DROP TABLE IF EXISTS "${table}";`)
    .join('\n');

  const sql = `-- Generated by \`npm run db:gen-auth -w server\` from Better Auth's own
-- migration planner (\`better-auth/db/migration\`#getMigrations). Do not
-- hand-edit the up section below — regenerate it instead, and add a new
-- migration file for any schema change on top of it. See README "Database".

-- migrate:up
${upSql}

-- migrate:down
${downSql}
`;

  const outPath = path.resolve(
    path.dirname(fileURLToPath(import.meta.url)),
    '..',
    'db',
    'migrations',
    '0001_auth.sql',
  );
  writeFileSync(outPath, sql);
  console.log(`wrote ${outPath}`);

  db.close();
}

main().catch((err) => {
  console.error('gen-auth-migration failed:', err);
  process.exitCode = 1;
});
